package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.UUID;
/** Direct counter sale of a repair part with immutable work-day FX snapshot. */
public final class DirectRepairPartSaleStore {private final CoreStore.DbProvider provider;private final String deviceId;public DirectRepairPartSaleStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result sell(String partId,int quantity,double unitPrice,double serviceFee,String currency,String paymentMethod)throws Exception{String pid=req(partId,"قطعة الصيانة"),cur=currency(currency),pay=req(paymentMethod,"طريقة الدفع").toUpperCase();if(quantity<=0)throw new IllegalArgumentException("الكمية يجب أن تكون أكبر من صفر");if(!Double.isFinite(unitPrice)||unitPrice<0||!Double.isFinite(serviceFee)||serviceFee<0)throw new IllegalArgumentException("السعر أو أجرة الخدمة غير صالحة");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;int before;double cost;try(Cursor c=db.rawQuery("SELECT name,quantity,unit_cost FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{pid})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");name=c.getString(0);before=c.getInt(1);cost=c.getDouble(2);}if(before<quantity)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");int after=before-quantity;double partsTotal=unitPrice*quantity,total=partsTotal+serviceFee;long now=System.currentTimeMillis();String saleId="partsale-"+UUID.randomUUID();ContentValues p=new ContentValues();p.put("quantity",after);p.put("updated_at",now);if(db.update("repair_inventory",p,"part_id=? AND deleted_at IS NULL",new String[]{pid})!=1)throw new IllegalStateException("تعذر تحديث رصيد قطعة الصيانة");ContentValues mv=new ContentValues();mv.put("move_id",saleId+"-stock");mv.put("part_id",pid);mv.put("source_type","DIRECT_SALE");mv.put("source_id",saleId);mv.put("before_qty",before);mv.put("delta_qty",-quantity);mv.put("after_qty",after);mv.put("created_at",now);db.insertOrThrow("repair_inventory_moves",null,mv);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR_PART_DIRECT",saleId,cur,total,now);if(total>0&&!"LATER".equals(pay)){ContentValues cash=new ContentValues();cash.put("move_id",saleId+"-cash");cash.put("source_type","REPAIR_PART_DIRECT");cash.put("source_id",saleId);cash.put("direction","IN");cash.put("amount",total);cash.put("currency",cur);cash.put("payment_method",pay);cash.put("drawer",drawer(pay));cash.put("created_at",now);db.insertOrThrow("cash_moves",null,cash);}JSONObject j=new JSONObject().put("saleId",saleId).put("saleType","REPAIR_PART_DIRECT").put("partId",pid).put("partName",name).put("quantity",quantity).put("beforeQty",before).put("afterQty",after).put("unitCost",cost).put("unitPrice",unitPrice).put("partsTotal",partsTotal).put("serviceFee",serviceFee).put("total",total).put("currency",cur).put("paymentMethod",pay).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("fxCapturedAt",fx.capturedAt).put("createdAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_CREATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(saleId,name,before,after,total,fx.usdAmount,cur,pay);}finally{db.endTransaction();}}
 private static String drawer(String pay){if("SHAM_CASH".equals(pay))return "SHAM_CASH";if("BANK".equals(pay))return "BANK";if("EXTERNAL".equals(pay))return "EXTERNAL";return "MAIN";}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}
 public static final class Result{public final String saleId,partName,currency,paymentMethod;public final int beforeQty,remainingQty;public final double total,totalUsd;Result(String id,String n,int b,int r,double t,double u,String c,String p){saleId=id;partName=n;beforeQty=b;remainingQty=r;total=t;totalUsd=u;currency=c;paymentMethod=p;}}
}
